package android.content.res;public final class ColorStateList {private final int[][] states;private final int[] colors;public ColorStateList(int[][] states,int[] colors){this.states=states.clone();this.colors=colors.clone();}public static ColorStateList valueOf(int color){return new ColorStateList(new int[][]{{}},new int[]{color});}public int getDefaultColor(){return colors[colors.length-1];}public int getColorForState(int[] state,int fallback){for(int i=0;i<states.length;i++){boolean matches=true;for(int required:states[i]){boolean found=false;for(int actual:state)if(actual==Math.abs(required))found=true;if(found!=(required>0)){matches=false;break;}}if(matches)return colors[i];}return fallback;}}
